raw:
{
  "slots": {
    "question": [
      {
        "claim": "Does the political climate where people live change the association between their own political conservatism and their hesitancy about or uptake of COVID-19 vaccines and boosters?",
        "quotes": [
          {
            "text": "The goal of the present research was to examine how political climate moderates\nthe relationship between self-reported political conservatism and COVID-19 vaccine\nhesitancy and uptake.",
            "page": 1
          },
          {
            "text": "While previous research has identified the unique impact\nof both political orientation and political climate on vaccination attitudes, there has\nbeen little research on the interaction between personal political orientation and local\npolitical climate.",
            "page": 2
          }
        ]
      },
      {
        "claim": "Do the patterns for attitudes and uptake differ between the initial vaccine and booster doses?",
        "quotes": [
          {
            "text": "Additionally, by looking at both COVID vaccine and booster status and hesitancy, we\nidentify how attitudes and behaviors may have shifted as we transitioned from initial vaccine doses to boosters.",
            "page": 7
          }
        ]
      }
    ],
    "central_claim": [
      {
        "claim": "Regional political climate mattered more for conservatives than for liberals: conservatives in more liberal areas were less hesitant about both initial vaccination and boosters and more likely to report getting a booster. The study did not find the same interaction for initial vaccine uptake.",
        "quotes": [
          {
            "text": "our findings indicate that political climate, as represented through regional 2020 presidential election votes,\nhas a stronger association with vaccine and booster hesitancy for individuals who are higher on political conservatism as\ncompared to those who are politically liberal.",
            "page": 8
          },
          {
            "text": "This same trend was observed for self-reported booster status, but not self-­\nreported vaccine status.",
            "page": 8
          },
          {
            "text": "However, conservatives living in liberal political climates were less vaccine hesitant than\ntheir conservative counterparts living in conservative regions.",
            "page": 1
          }
        ]
      }
    ],
    "evidence": [
      {
        "claim": "The study used an online, self-report survey of a nonprobability convenience sample recruited in the United States through Qualtrics Panels from March 8 to April 19, 2023.",
        "quotes": [
          {
            "text": "This was an online self-reported study in which a nonprobability convenience sample\nwas recruited from the United States between March 8 and April 19, 2023.",
            "page": 2
          },
          {
            "text": "Participants were a convenience sample recruited through Qualtrics Panels, an online research platform that manages\nparticipant recruitment and data quality for academic studies.",
            "page": 3
          }
        ]
      },
      {
        "claim": "The authors reanalyzed data originally collected for a project on racial and socioeconomic marginalization and COVID-19 vaccination.",
        "quotes": [
          {
            "text": "The data used in this study were part of a larger project assessing the impact of racial and socioeconomic marginalization on COVID-19 vaccine attitudes and behaviors [27]. The present research presents a novel analysis of the\ndataset from this project, focusing on political orientation and political climate, rather than marginalization.",
            "page": 4
          }
        ]
      },
      {
        "claim": "Recruitment quotas crossed Black or White racial identity with income above or below the $70,000 cutoff. The researchers requested that no gender account for more than 60% of any quota group.",
        "quotes": [
          {
            "text": "Half of the sample was requested to be White (and no other racial identity), and half the sample was requested\nto be Black (and no other racial identity). Within each racial group, half of the participants were requested to be below\nthe median annual income in the US [$70,000 [28]].",
            "page": 4
          },
          {
            "text": "Additionally, within each quota group it was requested that no more than 60% of the\nparticipants be of any gender.",
            "page": 4
          }
        ]
      },
      {
        "claim": "The final analytic sample was 683. Of 1,777 respondents, 970 failed Qualtrics quality screens, nine more were dropped for incoherent open-ended responses, and 115 lacked a valid ZIP code or matching election data.",
        "quotes": [
          {
            "text": "Qualtrics Panels collected data from 1777 participants, and identified 970 participants as not passing all quality screens\n(described above). We eliminated an additional nine participants whose open-ended responses did not make logical\nsense, resulting in a sample of 798 validated participants.",
            "page": 5
          },
          {
            "text": "We eliminated an additional 115 participants who did not provide valid zip code data (N = 100) or whose zip code did not have corresponding election data (N = 15). The final sample\nfor these analyses included 683 participants.",
            "page": 5
          }
        ]
      },
      {
        "claim": "The researchers required respondents to pass both Qualtrics’ data-quality screens and the study’s own attention checks.",
        "quotes": [
          {
            "text": "To ensure data quality, we only include participants in our analysis that pass both\nQualtrics Panels data quality screening and our own attention checks (S1 File), as recommended by previous research\nusing Qualtrics Panels [26].",
            "page": 4
          }
        ]
      },
      {
        "claim": "Participants were 18 to 94 years old; 519 reported initial vaccination and 365 reported at least one booster.",
        "quotes": [
          {
            "text": "Participants ranged in age from 18 to 94 years (M = 46.29, SD = 18.94). Demographic characteristics of the sample are\nshown in Table 1. 519 (76%) of participants reported receiving the initial COVID-19 vaccine and 365 (53%) reported\nreceiving at least one COVID-19 booster.",
            "page": 5
          }
        ]
      },
      {
        "claim": "The study received institutional review board approval before data collection, and participants gave written consent online.",
        "quotes": [
          {
            "text": "Ethical approval was obtained prior to data collection from the first author’s institutional review board (protocol ER-F22-35,\napproved on 1 October 2022) and all research was conducted in accordance with the Declaration of Helsinki. All participants completed an informed, written consent as part of the online survey.",
            "page": 4
          }
        ]
      },
      {
        "claim": "Individual political conservatism was measured by averaging two self-ratings, one on social issues and one on economic issues, each ranging from 0 for strongly liberal to 10 for strongly conservative.",
        "quotes": [
          {
            "text": "“social issues (for example, abortion, gun rights, gay rights)”. The second item, assessing economic conservatism (i.e., a\npolitical ideology that emphasizes free markets and lower taxes), aske participants to indicate their political orientation on\n“economic issues (for example, taxation, government spending)”.",
            "page": 3
          },
          {
            "text": "Both items were rated on a 11-point sliding scale from\nstrongly liberal (0) to strongly conservative (10). These two items were averaged to form a political conservatism scale.",
            "page": 3
          }
        ]
      },
      {
        "claim": "The proxy for regional conservatism was the Republican share of the 2020 presidential vote in each respondent’s ZIP code. The researchers linked ZIP codes to FIPS-coded election results and averaged the data when a ZIP code matched multiple FIPS codes.",
        "quotes": [
          {
            "text": "We assessed regional political climate using zip code data provided\nby participants and 2020 presidential election results sourced from the New York Times [22].",
            "page": 3
          },
          {
            "text": "Political climate for each participant was determined by matching FIPS codes to corresponding zip\ncodes. In cases where a zip code included multiple FIPS codes, data was averaged across these FIPS.",
            "page": 3
          },
          {
            "text": "Using the FIPS\ndata for each zip code, we calculated the percent of Republican votes by dividing the number of Republican votes by the\ntotal number of votes (multiplied by 100).",
            "page": 3
          }
        ]
      },
      {
        "claim": "Initial vaccination and booster receipt were measured with separate self-report questions. A booster meant a dose received after the initial series.",
        "quotes": [
          {
            "text": "Self-reported vaccine status and booster status were assessed through individual items, “have you received a COVID19 vaccine” and “have you received a COVID-19 booster”.",
            "page": 3
          },
          {
            "text": "The term “booster” is used in this analysis as this was the\ncommon term at the time to refer to subsequent doses of the COVID-19 vaccine after the initial vaccine series. Possible\nresponses were yes, no, and I don’t know.",
            "page": 3
          }
        ]
      },
      {
        "claim": "Initial vaccine hesitancy was measured with seven items from an adult vaccination attitudes scale adapted to COVID-19. Booster hesitancy was measured with items from a 2022 booster survey.",
        "quotes": [
          {
            "text": "Vaccine hesitancy (i.e., negative attitudes toward vaccination) was measured\nusing the seven items from the Attitudes towards Adult Vaccination Scale [24], which assesses the perceived value of\nvaccines in general.",
            "page": 3
          },
          {
            "text": "We modified the items to assess attitudes specifically toward the COVID-19 vaccine",
            "page": 3
          },
          {
            "text": "Each item was rated on a 5-point Likert scale ranging from disagree\nstrongly (1) to agree strongly (5). These items were averaged to form a vaccine hesitancy scale. Booster hesitancy was\nassessed using items from a 2022 survey on COVID-19 booster hesitancy [25].",
            "page": 3
          }
        ]
      },
      {
        "claim": "The authors used confirmatory factor analysis on the hesitancy items and averaged them into two scales. Both scales had a Cronbach’s alpha of .93.",
        "quotes": [
          {
            "text": "We conducted confirmatory factor analysis on the vaccine and booster hesitancy items (S2 File). The vaccine hesitancy items demonstrated adequate reliability (α = .93, 95% CI [.92,.93]) and were\naveraged to form the vaccine hesitancy scale. The booster hesitancy items demonstrated adequate reliability (α = .93, 95%\nCI [.93,.94]) and were averaged to form the booster hesitancy scale.",
            "page": 5
          }
        ]
      },
      {
        "claim": "Gender, race, income, and education were measured with single multiple-choice items. Perceived vaccine access was measured with one five-point item about how easily the respondent could get a vaccine or booster if needed.",
        "quotes": [
          {
            "text": "Demographic control variables (i.e., gender, race, income, and education) were assessed using single-item multi-option\nquestions.",
            "page": 3
          },
          {
            "text": "Perceived vaccine access was assessed using a single-item question “If I needed to get a COVID-19 vaccine\nor booster, I could easily get it”, rated on a 5-point Likert scale from Disagree Strongly (1) to Agree Strongly (5).",
            "page": 3
          }
        ]
      },
      {
        "claim": "The bivariate analyses used Pearson correlations for non-nominal variables and t-tests or chi-square tests for group comparisons.",
        "quotes": [
          {
            "text": "Pearson correlations were used to assess\ncorrelations between all non-nominal variables (i.e., age, income, education, perceived vaccine access, vaccine and\nbooster hesitancy, political conservatism, and conservative regional climate).",
            "page": 4
          },
          {
            "text": "Mean differences in categorical predictors (i.e., race and gender) across booster status and vaccine status were assessed using t-tests, and differences in\nfrequencies of vaccine status and booster status by gender and race were assessed using X2.",
            "page": 4
          },
          {
            "text": "Independent samples\nt-tests were used to assess differences in all non-nominal variables across vaccinated and unvaccinated participants.\nThe same analyses were run to assess differences between boosted and unboosted participants.",
            "page": 4
          }
        ]
      },
      {
        "claim": "The authors used ordinary least squares for hesitancy and logistic regression for uptake. For each outcome, they started with age, gender, education, income, race, and perceived access, then added the two political predictors, and finally added their interaction to test moderation.",
        "quotes": [
          {
            "text": "Ordinary least\nsquares estimation was used with default standard errors.",
            "page": 4
          },
          {
            "text": "Model 1 included only control variables age, gender, education, income, race, and vaccine access",
            "page": 4
          },
          {
            "text": "Model 2 included control variables and political conservatism and conservative regional climate. Model 3 included all variables from Model 2 and the interaction between\npolitical conservatism and conservative regional climate.",
            "page": 4
          },
          {
            "text": "Additionally, we ran two sets of generalized linear models with logit link\nand model-­based standard errors predicting vaccine status and booster status from the same three models described\nabove.",
            "page": 5
          }
        ]
      },
      {
        "claim": "Analyses excluded respondents with missing values on the variables being analyzed and used a two-sided significance threshold of .05.",
        "quotes": [
          {
            "text": "For all analyses, any participants with missing data on any of these variables were excluded from the analysis.",
            "page": 5
          },
          {
            "text": "Two-sided p-values less than 0.05 were\nconsidered statistically significant.",
            "page": 5
          }
        ]
      }
    ],
    "key_findings": [
      {
        "claim": "In the adjusted analyses, greater individual conservatism and a more conservative regional climate were each associated with more hesitancy about both doses and lower reported uptake of both.",
        "quotes": [
          {
            "text": "Political conservatism and conservative regional climate were both associated with higher levels of COVID-19 vaccine and booster hesitancy and lower rates of self-reported vaccination and boosting, when controlling for age, education, income, and race.",
            "page": 10
          }
        ]
      },
      {
        "claim": "Initial vaccine hesitancy was low among the most liberal respondents regardless of where they lived. Hesitancy rose with individual conservatism, more sharply in conservative areas.",
        "quotes": [
          {
            "text": "The interaction for vaccine hesitancy indicates that at the lowest levels of conservatism (i.e., liberalism) vaccine hesitancy is lower regardless of regional climate.\nAs political conservatism increases vaccine hesitancy also increases, but this increase is even greater for individuals\nwho live in a more conservative regional climate.",
            "page": 10
          }
        ]
      },
      {
        "claim": "Conservative respondents were more hesitant about boosters in conservative regions than in liberal regions. Among the most liberal respondents, booster hesitancy was slightly lower in more conservative regions.",
        "quotes": [
          {
            "text": "There was a similar pattern for booster hesitancy, with more politically\nconservative individuals in a conservative regional climate having higher booster hesitancy than conservative individuals\nin a liberal regional climate. For the most politically liberal individuals, booster hesitancy was slightly lower in more conservative regional climates.",
            "page": 10
          }
        ]
      },
      {
        "claim": "The estimated probability of booster receipt was above 65% for the most liberal respondents regardless of climate. For the most conservative respondents, it was about 60% in liberal areas and below 35% in conservative areas.",
        "quotes": [
          {
            "text": "Most strikingly, for booster status the interaction between political orientation and political climate\nindicated that the most liberal participants were over 65% likely to get boosted regardless of climate.",
            "page": 8
          },
          {
            "text": "The most conservative participants in liberal climates were 60% likely to get boosted, while conservatives in conservative climates were less\nthan 35% likely to get boosted (OR =.83, p = .026).",
            "page": 8
          }
        ]
      },
      {
        "claim": "The interaction between individual conservatism and regional political climate was not statistically significant for initial vaccine receipt.",
        "quotes": [
          {
            "text": "The interaction between political conservatism\nand conservative regional climate (Table 6) was not significant (OR = 1.02, p = .833).",
            "page": 7
          }
        ]
      }
    ],
    "scope_and_limits": [
      {
        "claim": "The study did not identify the mechanism behind higher booster uptake among conservatives in liberal areas. Social pressure is a possibility, not an explanation established by the data.",
        "quotes": [
          {
            "text": "While we did not asses the mechanism through which this occurs, these\nfindings suggest that environmental factors (e.g., social pressure) may impact decisions to receive annual COVID-19\ndoses.",
            "page": 10
          }
        ]
      },
      {
        "claim": "ZIP-code voting is only a proxy for political climate. Other local characteristics, such as population density, could account for the associations.",
        "quotes": [
          {
            "text": "Because we used 2020 presidential election votes by zip code as a proxy for political climate, it must be noted that\nother zip code-based differences could be driving the associations noted in this paper. Regional factors (e.g., population\ndensity) may play a role in linking 2020 election votes to vaccine attitudes and behaviors.",
            "page": 10
          }
        ]
      },
      {
        "claim": "Adjusting for demographics did not establish that the associations held within each demographic subgroup. The authors did not test demographic effect modification and cannot rule out aggregation effects such as Simpson’s paradox.",
        "quotes": [
          {
            "text": "While our analyses controlled\nfor demographic covariates commonly associated with vaccine hesitancy, we did not formally assess effect modification\nby these factors.",
            "page": 10
          },
          {
            "text": "Consequently, the reported pooled associations should be interpreted as average effects across the\nsample, and we cannot exclude the possibility that heterogeneity across demographic subgroups could produce aggregation effects such as Simpson’s paradox.",
            "page": 10
          }
        ]
      },
      {
        "claim": "Reported vaccination status may not match actual vaccination status because respondents may misremember or give socially desirable answers.",
        "quotes": [
          {
            "text": "Self-report is susceptible to social desirability [30] and recall bias [31], and we cannot assume that reported vaccine\nstatus reflects actual vaccine status.",
            "page": 10
          }
        ]
      },
      {
        "claim": "Online recruitment excluded people without access to the recruitment platform.",
        "quotes": [
          {
            "text": "Additionally, our sample was recruited through an online platform and only includes\nparticipants with access to this platform.",
            "page": 10
          }
        ]
      },
      {
        "claim": "The sample included only Black and White Qualtrics panelists, so the results may not generalize to the broader U.S. population.",
        "quotes": [
          {
            "text": "Further, our sample includes only White and Black participants recruited through\nQualtrics Panels, and may not generalize to broader populations in the United States.",
            "page": 10
          }
        ]
      },
      {
        "claim": "The cross-sectional data cannot establish causality or the direction of the associations.",
        "quotes": [
          {
            "text": "Finally, it should be noted that this\ndata is cross-sectional and we cannot assume causal or directional associations.",
            "page": 10
          }
        ]
      }
    ],
    "theoretical_positioning": [
      {
        "claim": "The authors extend empirical research on the political determinants of COVID-19 vaccination. They agree with earlier findings on individual ideology and regional climate, but combine the two lines of research by testing their interaction.",
        "quotes": [
          {
            "text": "Our research is consistent with previous findings that conservative political orientation and a conservative\npolitical climate are both associated with COVID-19 vaccine hesitancy and decreased likelihood of receiving a COVID-19\nvaccine [6,7,10,19].",
            "page": 10
          },
          {
            "text": "The present research provides the first assessment of the potential interaction between political orientation, political\nclimate, and COVID vaccination.",
            "page": 7
          }
        ]
      }
    ],
    "interlocutor_claim": [
      {
        "claim": "Hao and Shao reported that states with a larger Democratic presidential vote share in 2020 had higher COVID-19 booster rates in 2022. This paper builds on that aggregate finding by asking whether the link between political climate and booster receipt differs according to an individual’s own political orientation.",
        "quotes": [
          {
            "text": "Likewise, state-level 2020 Democratic presidential voting\nshare was associated with higher state-level COVID-19 booster rates in 2022 [20].",
            "page": 2
          },
          {
            "text": "By looking at political\norientation and region climate, we identify a novel and important finding, specifically that conservative individuals are more\nlikely to received booster doses in liberal regions.",
            "page": 10
          }
        ]
      }
    ]
  }
}
